<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Application\Policy\Filter;

use Throwable;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Service\Visibility\ClientIdentityRestrictFilterToVisibility;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TenantAccesible
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(ClientIdentityRestrictFilterToVisibility $event): ClientIdentityRestrictFilterToVisibility
    {
        $this->logDebug("Check TenantAccesible Client identity");
        $span = $this->startSpan("Check TenantAccesible Client identity");
        try {
            $userContext = $this->context->getIdentity();
            if (!$userContext->hasAnyRole('platform:*')) {
                if (!$userContext->anonymous && $userTenantTenantAccesible = $userContext->tenant) {
                    $event->clientIdentityFilter = $event->clientIdentityFilter->withUserTenantTenantAccesible($userTenantTenantAccesible);
                } else {
                    throw new UnauthorizedException('The claim tenant is required');
                }
            }
            return $event;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
